let cfgfile = "hiker://files/rules/Src/Juyue/config.json";
let Juconfig = {};
let Jucfg = fetch(cfgfile);
if (Jucfg != "") {
    eval("Juconfig=" + Jucfg + ";");
}
let proxylist = Juconfig['ghproxy'] || [];

function getproxy() {
    let list = proxylist.filter(v => !v.stop).map(it => it.url);
    if (list.length == 0) {
        try {
            let ghurls = 'https://www.github-mirrors.zone.id/api/urls';
            list = JSON.parse(fetch(ghurls)).data.map(url => {
                url = url.trim();
                if (!url.endsWith("/")) {
                    url = url + "/";
                }
                return url;
            });
            setproxy(list);
        } catch (e) {}
    }
    return list;
}

function getProxyUrl() {
    let proxy = getMyVar('SrcJu_proxyUrl', '');
    if (proxy == '') {
        let ghlist = getproxy();
        for (let item of ghlist) {
            let data = JSON.parse(fetch(item, {
                withStatusCode: true,
                timeout: 3000,
            }));
            if (data.statusCode == 200) {
                putMyVar('SrcJu_proxyUrl', item);
                proxy = item;
                break;
            } else {
                setproxy(item, 0);
            }
        }
    }
    return proxy;
}

function getSrcHome() {
    let srcHome = getItem('依赖', '');
    if (srcHome) {
        if (srcHome.startsWith('https://raw.github')) {
            let proxyUrl = getProxyUrl();
            srcHome = proxyUrl + srcHome;
        }
        try {
            let verify = fc(srcHome.replace(/[^/]*$/, '') + 'SrcVerify', 168);
            if (verify == 'ok') {
                return srcHome;
            }
        } catch (e) {}
    }
    try {
        let proxyUrl = getProxyUrl();
        require(proxyUrl + 'https://raw.githubusercontent.com/src48597962/hk/master/JuRequire.js', {
            timeout: 3000
        });
        let relyfile = getRely();
        if (relyfile) {
            srcHome = relyfile.includes('raw.github') ? proxyUrl + relyfile : relyfile;
            setItem('依赖', srcHome);
            log('获取代码库成功>' + srcHome);
        }
    } catch (e) {
        log('获取代码库异常>' + e.message);
    }
    return srcHome;
}

function setproxy(input, zt) {
    let list = [];
    if ($.type(input) == "string" && input.trim()) {
        list.push(input.trim());
    } else if ($.type(input) == "array") {
        list = input;
    }

    if (list.length > 0) {
        list.forEach(url => {
            let index = proxylist.findIndex(it => it.url == url);
            if (index == -1) {
                proxylist.push({
                    url: url
                });
            } else if (zt == 1) {
                delete proxylist[index].stop;
            } else if (zt == 0) {
                proxylist[index].stop = 1;
            } else if (zt == 2) {
                proxylist = proxylist.filter(v => v.url != url);
            }
        })
        Juconfig['ghproxy'] = proxylist;
        writeFile(cfgfile, JSON.stringify(Juconfig));
    }
}

function checkproxy(proxy) {
    let url = 'https://raw.githubusercontent.com/src48597962/hk/master/verify';
    let content = fetch(proxy + url, {
        timeout: 5000
    });
    if (content && content.trim() == 'ok') {
        return proxy;
    }
    return '';
}

function proxyPage() {
    setPageTitle('启动代理管理');
    proxylist.reverse();
    let withoutStop = proxylist.filter(item => !item.stop);
    let withStop = proxylist.filter(item => item.stop);
    let d = [];
    d.push({
        title: '选择代码库获取方式',
        desc: '有代理：' + proxylist.length + '，有效的：' + getproxy().length + '，长按批量管理',
        url: $(['方式一：自动获取代码库', '方式二：手工指定代码库'], 1, '指定聚阅代码获取方式').select(() => {
            if (MY_INDEX == 0) {
                return "toast://添加完有效的github加速代理后返回刷新";
            } else if (MY_INDEX == 1) {
                return $(getItem('依赖', ''), "指定聚阅代码仓地址").input(() => {
                    input = input.replace(/\s+/g, '');
                    if (!input.startsWith('http') || !input.endsWith('SrcJu.js')) {
                        return "toast://输入有误";
                    }
                    setItem('依赖', input);
                    refreshPage();
                    return "toast://已设置";
                })
            }
        }),
        col_type: "text_1",
        extra: {
            longClick: [{
                title: "批量检测",
                js: $.toString((checkproxy, lists) => {
                    lists = lists.map((item) => {
                        return {
                            func: checkproxy,
                            param: item.url,
                            id: item.url
                        }
                    });

                    if (lists.length > 0) {
                        showLoading(lists.length+'个代理批量检测中');
                        let fails = [];
                        be(lists, {
                            func: function(obj, id, error, taskResult) {
                                if (!taskResult) {
                                    fails.push(id);
                                }
                            },
                            param: {}
                        });
                        $.require('ghproxy').setproxy(fails, 0);
                        hideLoading();
                        refreshPage();
                        return "toast://批量检测结束";
                    }
                    return "hiker://empty";
                }, checkproxy, withoutStop)
            },{
                title: "删除失效",
                js: $.toString((lists)=>{
                    let fails = lists.map(item=>item.url);
                    $.require('ghproxy').setproxy(fails, 2);
                    refreshPage();
                    return "toast://已删除所有失效代理";
                }, withStop)
            },{
                title: "重置列表",
                js: $.toString((lists)=>{
                    let fails = lists.map(item=>item.url);
                    $.require('ghproxy').setproxy(fails, 2);
                    refreshPage();
                    return "toast://已清空代理并重新拉取，下拉刷新";
                }, proxylist)
            }]
        }
    });
    d.push({
        title: '添加',
        col_type: 'input',
        desc: '输入github加速代理地址',
        url: $.toString(() => {
            clearMyVar('get_ghproxy');
            input = input.trim();
            if (input && input.includes("/https")) {
                input = input.split("/http")[0] + "/";
            }
            if (!input.startsWith('http') || input.includes("githubusercontent.com") || !input.endsWith("/")) {
                return "toast://输入错误，请输入正确的github加速代理";
            }
            $.require('ghproxy').setproxy(input);
            refreshPage();
            return "hiker://empty";
        }),
        extra: {
            defaultValue: getMyVar('get_ghproxy', ''),
            titleVisible: true
        }
    });
    d.push({
        col_type: "line"
    });
    withoutStop.concat(withStop).forEach(it => {
        d.push({
            title: it.stop ? '‘‘’’<font color="#f20c00">' + it.url + '</font>' : it.url,
            url: $([it.stop ? "启用" : "停用", "删除", "复制", "检测"], 1, "").select((url, checkproxy) => {
                if (input == "启用") {
                    $.require('ghproxy').setproxy(url, 1);
                } else if (input == "停用") {
                    $.require('ghproxy').setproxy(url, 0);
                } else if (input == "删除") {
                    $.require('ghproxy').setproxy(url, 2);
                } else if (input == "复制") {
                    copy(url);
                    return "hiker://empty";
                } else if (input == "检测") {
                    showLoading('检测中');
                    let ghproxy = checkproxy(url);
                    hideLoading();
                    if (ghproxy) {
                        return 'toast://成功';
                    } else {
                        $.require('ghproxy').setproxy(url, 0);
                        refreshPage(false);
                        return 'toast://失败，已停用';
                    }
                }
                refreshPage(false);
                return "hiker://empty";
            }, it.url, checkproxy),
            col_type: "text_1",
            extra: {
                id: it.url
            }
        });
    })
    setResult(d);
}
